import{_ as e,o as t,c as o,Q as a}from"./chunks/framework.b67c47e6.js";const n="/assets/production-excel.d315a486.svg",_=JSON.parse('{"title":"Production Excel","description":"","frontmatter":{},"headers":[],"relativePath":"guide/reports/production_excel/index.md","filePath":"guide/reports/production_excel/index.md","lastUpdated":1790346505000}'),r={name:"guide/reports/production_excel/index.md"},s=a('<h1 id="production-excel" tabindex="-1">Production Excel <a class="header-anchor" href="#production-excel" aria-label="Permalink to &quot;Production Excel&quot;">​</a></h1><p>The Production Excel generates a spreadsheet with one row per panel of the project, with its dimensions, areas, weight and openings. It is listed in <strong>Production files</strong>.</p><p><img src="'+n+'" alt="The Production Excel sheet"></p><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><ul><li><strong>Format:</strong> Excel (.xlsx)</li><li><strong>Content:</strong> One sheet. The first row holds the company name and the project name. Then one row per assembly with these columns:</li></ul><table><thead><tr><th>Column</th><th>Unit</th></tr></thead><tbody><tr><td>Phase, Batch, Order, Design</td><td></td></tr><tr><td>Count</td><td>always 1</td></tr><tr><td>Length, Height, Thickness</td><td>mm</td></tr><tr><td>Wall Area, Net Area, Opening Area</td><td>m²</td></tr><tr><td>Weight</td><td>kg</td></tr><tr><td>Opening 1 … Opening 4</td><td>name of each opening</td></tr></tbody></table><p>A <strong>TOTALS</strong> row at the bottom adds up the count, the three areas and the weight. The header rows stay frozen while you scroll.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>Generate it inside a project: it always includes every assembly of the project, so there is no panel selection. Modules are not included.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The company-wide Production files also offer the Production Excel, but there it has no way to pick panels yet and produces a sheet with headers only.</p></div><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><p>There are no document settings. Only the <strong>Document comment</strong> and <strong>Document status</strong> of the report form apply.</p><h2 id="when-to-use" tabindex="-1">When to Use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to Use&quot;">​</a></h2><p>Use this report for production planning meetings, or when you need the panel sizes and areas of a project in a spreadsheet.</p>',14),i=[s];function d(c,h,l,p,u,m){return t(),o("div",null,i)}const x=e(r,[["render",d]]);export{_ as __pageData,x as default};
